SELECT CASE WHEN ss.units >= 37 THEN 'high' WHEN ss.units >= 17 THEN 'mid' ELSE 'low' END AS units_bucket, MIN(i.quantity) AS min_quantity, MIN(i.last_restock) AS first_last_restock FROM inventory i INNER JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id WHERE ss.store_id IN (5, 6) GROUP BY CASE WHEN ss.units >= 37 THEN 'high' WHEN ss.units >= 17 THEN 'mid' ELSE 'low' END;
